Here is the commit message:
can: ems_usb: ems_usb_read_bulk_callback(): fix URB memory
 leak

Fix similar memory leak as in commit 7352e1d5932a ("can: gs_usb:
gs_usb_receive_bulk_callback(): fix URB memory leak").

In ems_usb_open(), the URBs for USB-in transfers are allocated, added to
the dev->rx_submitted anchor and submitted. In the complete callback
ems_usb_read_bulk_callback(), the URBs are processed and resubmitted. In
ems_usb_close() the URBs are freed by calling
usb_kill_anchored_urbs(&dev->rx_submitted).

However, this does not take into account that the USB framework unanchors
the URB before the complete function is called. This means that once an
in-URB has been completed, it is no longer anchored and is ultimately not
released in ems_usb_close().

Fix the memory leak by anchoring the URB in the
ems_usb_read_bulk_callback() to the dev->rx_submitted anchor.

Fixes: 702171adeed3 ("ems_usb: Added support for EMS CPC-USB/ARM7 CAN/USB interface")
Cc: stable@vger.kernel.org
Link: https://patch.msgid.link/20260116-can_usb-fix-memory-leak-v2-1-4b8cb2915571@pengutronix.de
Signed-off-by: Marc Kleine-Budde <mkl@pengutronix.de>

Here is the root cause:
In the USB subsystem, the URB is automatically unanchored from the anchor list before the completion callback is invoked. In `ems_usb_read_bulk_callback()`, the URB was processed and resubmitted without re-anchoring it. Consequently, after the first completion, the URB was no longer part of the `dev->rx_submitted` anchor list. When `ems_usb_close()` called `usb_kill_anchored_urbs()`, it only frees URBs that are still anchored, so the completed URBs were never freed, causing a memory leak.

Here is the patch:
  */
 static void ems_usb_read_bulk_callback(struct urb *urb)
 {
 	struct ems_usb *dev = urb->context;
 	struct net_device *netdev;
 	int retval;

 	netdev = dev->netdev;

 	if (!netif_device_present(netdev))
 		return;

 	switch (urb->status) {
 	case 0: /* success */
 		break;

 	case -ENOENT:
 		return;

 	default:
 		netdev_info(netdev, "Rx URB aborted (%d)\n", urb->status);
 		goto resubmit_urb;
 	}

 	if (urb->actual_length > CPC_HEADER_SIZE) {
 		struct ems_cpc_msg *msg;
 		u8 *ibuf = urb->transfer_buffer;
 		u8 msg_count, start;

 		msg_count = ibuf[0] & ~0x80;

 		start = CPC_HEADER_SIZE;

 		while (msg_count) {
 			msg = (struct ems_cpc_msg *)&ibuf[start];

 			switch (msg->type) {
 			case CPC_MSG_TYPE_CAN_STATE:
 				/* Process CAN state changes */
 				ems_usb_rx_err(dev, msg);
 				break;

 			case CPC_MSG_TYPE_CAN_FRAME:
 			case CPC_MSG_TYPE_EXT_CAN_FRAME:
 			case CPC_MSG_TYPE_RTR_FRAME:
 			case CPC_MSG_TYPE_EXT_RTR_FRAME:
 				ems_usb_rx_can_msg(dev, msg);
 				break;

 			case CPC_MSG_TYPE_CAN_FRAME_ERROR:
 				/* Process errorframe */
 				ems_usb_rx_err(dev, msg);
 				break;

 			case CPC_MSG_TYPE_OVERRUN:
 				/* Message lost while receiving */
 				ems_usb_rx_err(dev, msg);
 				break;
 			}

 			start += CPC_MSG_HEADER_LEN + msg->length;
 			msg_count--;

 			if (start > urb->transfer_buffer_length) {
 				netdev_err(netdev, "format error\n");
 				break;
 			}
 		}
 	}

 resubmit_urb:
 	usb_fill_bulk_urb(urb, dev->udev, usb_rcvbulkpipe(dev->udev, 2),
 			  urb->transfer_buffer, RX_BUFFER_SIZE,
 			  ems_usb_read_bulk_callback, dev);

+	usb_anchor_urb(urb, &dev->rx_submitted);
+
 	retval = usb_submit_urb(urb, GFP_ATOMIC);
+	if (!retval)
+		return;
+
+	usb_unanchor_urb(urb);

 	if (retval == -ENODEV)
 		netif_device_detach(netdev);
-	else if (retval)
+	else
 		netdev_err(netdev,
 			   "failed resubmitting read bulk urb: %d\n", retval);
 }



